CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('admin','editor','reviewer','operations')),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.admin_can(p_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role='admin' OR (p_permission IN ('content','edit') AND role='editor') OR (p_permission IN ('content','publish') AND role='reviewer') OR (p_permission IN ('users','reports') AND role='operations'))); $$;
REVOKE ALL ON FUNCTION public.admin_can(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_can(text) TO authenticated;
CREATE POLICY admin_role_read ON public.user_roles FOR SELECT TO authenticated USING(public.admin_can('roles'));
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor uuid,action text NOT NULL,entity_id text NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated; GRANT ALL ON public.admin_audit TO service_role; ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.admin_audit FOR SELECT TO authenticated USING(public.admin_can('audit'));
CREATE TABLE public.question_drafts (id text PRIMARY KEY,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','verified','published','offline')),revision integer NOT NULL DEFAULT 1,updated_by uuid,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.question_drafts TO authenticated; GRANT ALL ON public.question_drafts TO service_role; ALTER TABLE public.question_drafts ENABLE ROW LEVEL SECURITY; CREATE POLICY draft_read ON public.question_drafts FOR SELECT TO authenticated USING(public.admin_can('content'));
CREATE TABLE public.question_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id text NOT NULL,revision integer NOT NULL,payload jsonb NOT NULL,status text NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(question_id,revision));
GRANT SELECT ON public.question_versions TO authenticated; GRANT ALL ON public.question_versions TO service_role; ALTER TABLE public.question_versions ENABLE ROW LEVEL SECURITY; CREATE POLICY version_read ON public.question_versions FOR SELECT TO authenticated USING(public.admin_can('content'));
ALTER TABLE public.learning_questions ADD COLUMN option_ids text[] NOT NULL DEFAULT ARRAY['a','b','c','d'], ADD COLUMN correct_option_id text, ADD COLUMN content_revision integer NOT NULL DEFAULT 1, ADD COLUMN pathways text[] NOT NULL DEFAULT ARRAY['naturalisation','resident','sejour'];
UPDATE public.learning_questions SET correct_option_id=option_ids[answer+1];
INSERT INTO public.question_drafts(id,payload,status) SELECT id,jsonb_build_object('id',id,'question',question,'options',(SELECT jsonb_agg(jsonb_build_object('id',q.option_ids[n],'text',v) ORDER BY n) FROM unnest(q.options) WITH ORDINALITY a(v,n)),'correct_option_id',correct_option_id,'explanation',explanation,'theme',theme,'exam_theme',coalesce(exam_theme,'Droits et devoirs'),'pathways',to_jsonb(pathways),'difficulty','standard','source',source,'source_url',coalesce(source_url,''),'lesson_id',coalesce(lesson_id,''),'translations','{}'::jsonb,'image_url',''),'draft' FROM public.learning_questions q;
INSERT INTO public.question_versions(question_id,revision,payload,status) SELECT id,revision,payload,status FROM public.question_drafts;
CREATE TABLE public.admin_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor uuid NOT NULL,filename text NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_imports TO authenticated; GRANT ALL ON public.admin_imports TO service_role; ALTER TABLE public.admin_imports ENABLE ROW LEVEL SECURITY; CREATE POLICY imports_read ON public.admin_imports FOR SELECT TO authenticated USING(public.admin_can('content'));
CREATE TABLE public.learning_tests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,kind text NOT NULL CHECK(kind IN ('free','theme','practice','review','exam')),pathways text[] NOT NULL DEFAULT ARRAY['naturalisation','resident','sejour'],themes text[] NOT NULL DEFAULT '{}',question_count integer NOT NULL DEFAULT 10 CHECK(question_count BETWEEN 1 AND 100),duration_minutes integer NOT NULL DEFAULT 0 CHECK(duration_minutes BETWEEN 0 AND 180),selection text NOT NULL DEFAULT 'rules' CHECK(selection IN ('rules','fixed')),question_ids text[] NOT NULL DEFAULT '{}',instant_feedback boolean NOT NULL DEFAULT true,allow_aids boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','offline')),revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_tests TO anon,authenticated; GRANT ALL ON public.learning_tests TO service_role; ALTER TABLE public.learning_tests ENABLE ROW LEVEL SECURITY; CREATE POLICY published_tests ON public.learning_tests FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY managed_tests ON public.learning_tests FOR SELECT TO authenticated USING(public.admin_can('content'));
ALTER TABLE public.learning_sessions ADD COLUMN test_id uuid REFERENCES public.learning_tests(id), ADD COLUMN test_rules jsonb;
CREATE TABLE public.admin_translations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id text NOT NULL,locale text NOT NULL CHECK(locale IN ('zh','en','ar','es','ru')),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewed')),source_revision integer NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(question_id,locale));
GRANT SELECT ON public.admin_translations TO authenticated; GRANT ALL ON public.admin_translations TO service_role; ALTER TABLE public.admin_translations ENABLE ROW LEVEL SECURITY; CREATE POLICY translation_read ON public.admin_translations FOR SELECT TO authenticated USING(public.admin_can('content'));
CREATE TABLE public.admin_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,url text NOT NULL,lesson_id text REFERENCES public.learning_lessons(id),kind text NOT NULL CHECK(kind IN ('image','video','audio')),language text NOT NULL DEFAULT 'fr',source text NOT NULL DEFAULT '',rights text NOT NULL DEFAULT '',verified boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_media TO authenticated; GRANT ALL ON public.admin_media TO service_role; ALTER TABLE public.admin_media ENABLE ROW LEVEL SECURITY; CREATE POLICY media_read ON public.admin_media FOR SELECT TO authenticated USING(public.admin_can('content'));
CREATE TABLE public.question_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),question_id text NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 5 AND 2000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','assigned','closed')),reply text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.question_reports TO authenticated; GRANT ALL ON public.question_reports TO service_role; ALTER TABLE public.question_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY report_own_insert ON public.question_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='open' AND reply=''); CREATE POLICY report_own_read ON public.question_reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.admin_can('reports'));
CREATE TABLE public.lesson_drafts (id text PRIMARY KEY,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lesson_drafts TO authenticated; GRANT ALL ON public.lesson_drafts TO service_role; ALTER TABLE public.lesson_drafts ENABLE ROW LEVEL SECURITY; CREATE POLICY lesson_draft_read ON public.lesson_drafts FOR SELECT TO authenticated USING(public.admin_can('content'));
INSERT INTO public.lesson_drafts(id,payload,status) SELECT id,to_jsonb(l),'draft' FROM public.learning_lessons l;
CREATE FUNCTION public.admin_validate_question(p jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE ids text[]; correct text; BEGIN IF coalesce(p->>'id','') !~ '^[A-Za-z0-9_-]{1,100}$' OR length(trim(coalesce(p->>'question','')))<8 OR length(trim(coalesce(p->>'explanation','')))<8 OR jsonb_typeof(p->'options') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'options')<>4 THEN RAISE EXCEPTION 'Question invalide : ID, texte, explication et quatre options requis.'; END IF;
SELECT array_agg(x->>'id') INTO ids FROM jsonb_array_elements(p->'options') x; correct:=p->>'correct_option_id'; IF (SELECT count(DISTINCT x) FROM unnest(ids) x)<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'options') x WHERE coalesce(x->>'id','')='' OR trim(coalesce(x->>'text',''))='') OR correct IS NULL OR NOT(correct=ANY(ids)) THEN RAISE EXCEPTION 'Identifiants des options ou bonne réponse invalides.'; END IF;
IF coalesce(p->>'theme','') NOT IN ('Principes et valeurs de la République française','Système institutionnel et politique','Droits et devoirs','Histoire, géographie et culture','Vivre dans la société française','Institutions','Institutions françaises','Valeurs de la République','Principes et valeurs','Histoire','France et Europe') OR coalesce(p->>'exam_theme','') NOT IN ('Institutions','Valeurs de la République','Histoire','Droits et devoirs','France et Europe') OR jsonb_typeof(p->'pathways') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'pathways')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'pathways') x WHERE x NOT IN ('naturalisation','resident','sejour')) THEN RAISE EXCEPTION 'Thème ou parcours invalide.'; END IF;
IF coalesce(p->>'difficulty','') NOT IN ('easy','standard','hard') THEN RAISE EXCEPTION 'Difficulté invalide.'; END IF;
IF coalesce(p->>'lesson_id','')<>'' AND NOT EXISTS(SELECT 1 FROM public.learning_lessons WHERE id=p->>'lesson_id') THEN RAISE EXCEPTION 'Leçon inconnue.'; END IF;
IF EXISTS(SELECT 1 FROM public.question_drafts WHERE id<>p->>'id' AND lower(regexp_replace(payload->>'question','\s+',' ','g'))=lower(regexp_replace(p->>'question','\s+',' ','g'))) THEN RAISE EXCEPTION 'Un autre ID utilise déjà ce texte de question.'; END IF;
IF coalesce(p->'translations','{}'::jsonb)<>'{}'::jsonb THEN IF jsonb_typeof(p->'translations')<>'object' THEN RAISE EXCEPTION 'Traductions invalides.'; END IF; IF EXISTS(SELECT 1 FROM jsonb_each(p->'translations') t WHERE t.key NOT IN ('zh','en','ar','es','ru') OR coalesce(t.value->>'question','')='' OR jsonb_typeof(t.value->'options') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM unnest(ids) oid WHERE coalesce(t.value->'options'->>oid,'')='') OR (SELECT count(*) FROM jsonb_object_keys(t.value->'options'))<>4) THEN RAISE EXCEPTION 'Les traductions doivent correspondre aux identifiants des quatre options.'; END IF; END IF;
END $$;
REVOKE ALL ON FUNCTION public.admin_validate_question(jsonb) FROM PUBLIC;
CREATE FUNCTION public.admin_command(p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE permission text; entity text; old jsonb; result jsonb; q public.question_drafts; p jsonb; opts text[]; ids text[]; rows jsonb:='[]'; errors integer:=0; duplicates integer:=0; successes integer:=0; x jsonb; t public.learning_tests; role_count integer; BEGIN
permission:=CASE WHEN p_action IN ('question_save','question_import','question_submit','question_restore','test_save','lesson_save','translation_save','media_save') THEN 'edit' WHEN p_action IN ('question_verify','question_publish','question_offline','test_publish','test_offline','translation_review','lesson_publish','media_verify') THEN 'publish' WHEN p_action='role_set' THEN 'roles' WHEN p_action='report_update' THEN 'reports' ELSE 'none' END;
IF NOT public.admin_can(permission) THEN RAISE EXCEPTION 'Accès refusé : permission requise.' USING ERRCODE='42501'; END IF; entity:=coalesce(p_data->>'id','');
IF p_action='question_import' THEN
 IF jsonb_typeof(p_data->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'rows')>500 THEN RAISE EXCEPTION 'Import limité à 500 lignes.'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_data->'rows') LOOP
 BEGIN p:=x->'payload'; PERFORM public.admin_validate_question(p); SELECT * INTO q FROM public.question_drafts WHERE id=p->>'id' FOR UPDATE; old:=to_jsonb(q);
 IF FOUND AND q.payload=p THEN duplicates:=duplicates+1;rows:=rows||jsonb_build_array(jsonb_build_object('row',x->'row','id',p->>'id','status','duplicate')); CONTINUE; END IF;
 IF q.id IS NOT NULL AND (NOT coalesce((x->>'update')::boolean,false) OR coalesce((x->>'revision')::integer,0)<>q.revision) THEN RAISE EXCEPTION 'Modification non confirmée ou version modifiée : relancez la prévisualisation.'; END IF;
 INSERT INTO public.question_drafts(id,payload,updated_by) VALUES(p->>'id',p,auth.uid()) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,status='draft',revision=question_drafts.revision+1,updated_by=auth.uid(),updated_at=now() RETURNING * INTO q;
 INSERT INTO public.question_versions(question_id,revision,payload,status,created_by) VALUES(q.id,q.revision,q.payload,q.status);
 INSERT INTO public.admin_audit(actor,action,entity_id,before_data,after_data) VALUES(auth.uid(),'question_import',q.id,old,to_jsonb(q));
 INSERT INTO public.admin_translations(question_id,locale,payload,source_revision) SELECT q.id,key,value,q.revision FROM jsonb_each(coalesce(p->'translations','{}')) ON CONFLICT(question_id,locale) DO UPDATE SET payload=excluded.payload,source_revision=excluded.source_revision,status='pending',updated_at=now();
 successes:=successes+1; rows:=rows||jsonb_build_array(jsonb_build_object('row',x->'row','id',q.id,'status','draft'));
 EXCEPTION WHEN OTHERS THEN errors:=errors+1; rows:=rows||jsonb_build_array(jsonb_build_object('row',x->'row','id',x->'payload'->>'id','status','error','message',SQLERRM)); END; END LOOP;
 result:=jsonb_build_object('success',successes,'failed',errors,'duplicates',duplicates,'pending_review',successes,'rows',rows);
 INSERT INTO public.admin_imports(actor,filename,report) VALUES(auth.uid(),coalesce(p_data->>'filename','import'),result); RETURN result;
ELSIF p_action LIKE 'question_%' THEN
 SELECT * INTO q FROM public.question_drafts WHERE id=entity FOR UPDATE; old:=to_jsonb(q);
 IF p_action='question_save' THEN p:=p_data->'payload'; PERFORM public.admin_validate_question(p); IF p->>'id'<>entity THEN RAISE EXCEPTION 'ID stable non modifiable.'; END IF;
 IF q.id IS NOT NULL AND coalesce((p_data->>'revision')::integer,0)<>q.revision THEN RAISE EXCEPTION 'Cette question a été modifiée. Rechargez-la.'; END IF;
 INSERT INTO public.question_drafts(id,payload,updated_by) VALUES(entity,p,auth.uid()) ON CONFLICT(id) DO UPDATE SET payload=p,status='draft',revision=question_drafts.revision+1,updated_by=auth.uid(),updated_at=now() RETURNING * INTO q;
 ELSIF q.id IS NULL THEN RAISE EXCEPTION 'Question introuvable.';
 ELSIF p_action='question_restore' THEN SELECT payload INTO p FROM public.question_versions WHERE question_id=entity AND revision=(p_data->>'version')::integer; IF p IS NULL THEN RAISE EXCEPTION 'Version inconnue.'; END IF; PERFORM public.admin_validate_question(p);UPDATE public.question_drafts SET payload=p,status='draft',revision=revision+1,updated_at=now(),updated_by=auth.uid() WHERE id=entity RETURNING * INTO q;
 ELSIF p_action='question_submit' THEN IF q.status<>'draft' OR coalesce(q.payload->>'source_url','') !~ '^https://' OR coalesce(q.payload->>'source','')='' THEN RAISE EXCEPTION 'Une source HTTPS et un brouillon sont requis.'; END IF;UPDATE public.question_drafts SET status='pending',revision=revision+1,updated_at=now(),updated_by=auth.uid() WHERE id=entity RETURNING * INTO q;
 ELSIF p_action='question_verify' THEN IF q.status<>'pending' THEN RAISE EXCEPTION 'Soumettez la question à la vérification.'; END IF;UPDATE public.question_drafts SET status='verified',revision=revision+1,updated_at=now(),updated_by=auth.uid() WHERE id=entity RETURNING * INTO q;
 ELSIF p_action='question_publish' THEN IF q.status<>'verified' THEN RAISE EXCEPTION 'Question non vérifiée : publication refusée.'; END IF;PERFORM public.admin_validate_question(q.payload); IF coalesce(q.payload->>'source_url','') !~ '^https://' OR coalesce(q.payload->>'source','')='' THEN RAISE EXCEPTION 'Source requise.'; END IF;
 SELECT array_agg(o->>'text' ORDER BY n),array_agg(o->>'id' ORDER BY n) INTO opts,ids FROM jsonb_array_elements(q.payload->'options') WITH ORDINALITY a(o,n);
 PERFORM pg_advisory_xact_lock(763100); INSERT INTO public.learning_questions(id,theme,question,options,answer,explanation,source,source_url,lesson_id,exam_theme,position,published,option_ids,correct_option_id,content_revision,pathways,source_status,source_verified_at) VALUES(entity,q.payload->>'theme',q.payload->>'question',opts,array_position(ids,q.payload->>'correct_option_id')-1,q.payload->>'explanation',q.payload->>'source',q.payload->>'source_url',nullif(q.payload->>'lesson_id',''),q.payload->>'exam_theme',(SELECT coalesce(max(position),0)+1 FROM public.learning_questions),true,ids,q.payload->>'correct_option_id',q.revision+1,ARRAY(SELECT jsonb_array_elements_text(q.payload->'pathways')),'verifie',now()) ON CONFLICT(id) DO UPDATE SET theme=excluded.theme,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,source=excluded.source,source_url=excluded.source_url,lesson_id=excluded.lesson_id,exam_theme=excluded.exam_theme,published=true,option_ids=excluded.option_ids,correct_option_id=excluded.correct_option_id,content_revision=excluded.content_revision,pathways=excluded.pathways,source_status='verifie',source_verified_at=now(); UPDATE public.question_drafts SET status='published',revision=revision+1,updated_at=now(),updated_by=auth.uid() WHERE id=entity RETURNING * INTO q;
 ELSIF p_action='question_offline' THEN UPDATE public.learning_questions SET published=false WHERE id=entity;UPDATE public.question_drafts SET status='offline',revision=revision+1,updated_at=now(),updated_by=auth.uid() WHERE id=entity RETURNING * INTO q;
 ELSE RAISE EXCEPTION 'Action inconnue.'; END IF;
 INSERT INTO public.question_versions(question_id,revision,payload,status,created_by) VALUES(q.id,q.revision,q.payload,q.status); result:=to_jsonb(q);
ELSIF p_action LIKE 'test_%' THEN
 SELECT to_jsonb(z) INTO old FROM public.learning_tests z WHERE id=nullif(entity,'')::uuid FOR UPDATE;
 IF p_action='test_save' THEN p:=p_data->'payload'; entity:=coalesce(nullif(entity,''),gen_random_uuid()::text);
 INSERT INTO public.learning_tests(id,title,kind,pathways,themes,question_count,duration_minutes,selection,question_ids,instant_feedback,allow_aids) VALUES(entity::uuid,p->>'title',p->>'kind',ARRAY(SELECT jsonb_array_elements_text(p->'pathways')),ARRAY(SELECT jsonb_array_elements_text(p->'themes')),(p->>'question_count')::integer,(p->>'duration_minutes')::integer,p->>'selection',ARRAY(SELECT jsonb_array_elements_text(p->'question_ids')),(p->>'instant_feedback')::boolean,(p->>'allow_aids')::boolean) ON CONFLICT(id) DO UPDATE SET title=excluded.title,kind=excluded.kind,pathways=excluded.pathways,themes=excluded.themes,question_count=excluded.question_count,duration_minutes=excluded.duration_minutes,selection=excluded.selection,question_ids=excluded.question_ids,instant_feedback=excluded.instant_feedback,allow_aids=excluded.allow_aids,status='draft',revision=learning_tests.revision+1,updated_at=now();
 ELSIF p_action='test_publish' THEN SELECT * INTO t FROM public.learning_tests WHERE id=entity::uuid; IF t.id IS NULL OR trim(t.title)='' OR cardinality(t.pathways)=0 OR NOT(t.pathways<@ARRAY['naturalisation','resident','sejour']) OR (t.kind='free' AND t.question_count<>10) OR (t.kind='exam' AND t.duration_minutes=0) THEN RAISE EXCEPTION 'Règles du test invalides (test gratuit : 10 questions ; examen : durée requise).'; END IF;
 IF t.selection='fixed' AND (cardinality(t.question_ids)<>t.question_count OR (SELECT count(DISTINCT v) FROM unnest(t.question_ids) v)<>t.question_count) THEN RAISE EXCEPTION 'Liste fixe incomplète ou doublonnée.'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(t.pathways) path WHERE (SELECT count(*) FROM public.learning_questions WHERE published AND path=ANY(pathways) AND (cardinality(t.themes)=0 OR theme=ANY(t.themes) OR exam_theme=ANY(t.themes)) AND (t.selection<>'fixed' OR id=ANY(t.question_ids)))<t.question_count) THEN RAISE EXCEPTION 'Nombre de questions publiées insuffisant pour un parcours.'; END IF;
 UPDATE public.learning_tests SET status='published',revision=revision+1,updated_at=now() WHERE id=t.id;
 ELSIF p_action='test_offline' THEN UPDATE public.learning_tests SET status='offline',revision=revision+1,updated_at=now() WHERE id=entity::uuid; END IF; SELECT to_jsonb(z) INTO result FROM public.learning_tests z WHERE id=entity::uuid;
ELSIF p_action='role_set' THEN
 IF p_data->>'role' NOT IN ('admin','editor','reviewer','operations') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=entity::uuid) THEN RAISE EXCEPTION 'Rôle ou compte invalide.'; END IF;
 PERFORM pg_advisory_xact_lock(763101); SELECT jsonb_agg(to_jsonb(r)) INTO old FROM public.user_roles r WHERE user_id=entity::uuid;
 IF coalesce((p_data->>'enabled')::boolean,false) THEN INSERT INTO public.user_roles(user_id,role) VALUES(entity::uuid,p_data->>'role') ON CONFLICT DO NOTHING;
 ELSE IF p_data->>'role'='admin' AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=entity::uuid AND role='admin') AND (SELECT count(*) FROM public.user_roles WHERE role='admin')<=1 THEN RAISE EXCEPTION 'Le dernier administrateur ne peut pas être retiré.'; END IF;DELETE FROM public.user_roles WHERE user_id=entity::uuid AND role=p_data->>'role'; END IF;SELECT jsonb_agg(to_jsonb(r)) INTO result FROM public.user_roles r WHERE user_id=entity::uuid;
ELSIF p_action LIKE 'translation_%' THEN
 SELECT to_jsonb(z) INTO old FROM public.admin_translations z WHERE question_id=entity AND locale=p_data->>'locale';
 IF p_action='translation_save' THEN SELECT * INTO q FROM public.question_drafts WHERE id=entity;PERFORM public.admin_validate_question(q.payload||jsonb_build_object('translations',jsonb_build_object(p_data->>'locale',p_data->'payload')));INSERT INTO public.admin_translations(question_id,locale,payload,source_revision) VALUES(entity,p_data->>'locale',p_data->'payload',q.revision) ON CONFLICT(question_id,locale) DO UPDATE SET payload=excluded.payload,source_revision=excluded.source_revision,status='pending',updated_at=now();
 ELSE UPDATE public.admin_translations SET status='reviewed',updated_at=now() WHERE question_id=entity AND locale=p_data->>'locale' AND source_revision=(SELECT revision FROM public.question_drafts WHERE id=entity);IF NOT FOUND THEN RAISE EXCEPTION 'Traduction absente ou source modifiée.'; END IF; END IF; SELECT to_jsonb(z) INTO result FROM public.admin_translations z WHERE question_id=entity AND locale=p_data->>'locale';
ELSIF p_action LIKE 'media_%' THEN
 IF p_action='media_save' THEN p:=p_data->'payload';IF coalesce(p->>'url','') !~ '^https://' THEN RAISE EXCEPTION 'Adresse HTTPS requise.'; END IF;entity:=coalesce(nullif(entity,''),gen_random_uuid()::text); SELECT to_jsonb(z) INTO old FROM public.admin_media z WHERE id=entity::uuid;INSERT INTO public.admin_media(id,title,url,lesson_id,kind,language,source,rights) VALUES(entity::uuid,p->>'title',p->>'url',nullif(p->>'lesson_id',''),p->>'kind',p->>'language',p->>'source',p->>'rights') ON CONFLICT(id) DO UPDATE SET title=excluded.title,url=excluded.url,lesson_id=excluded.lesson_id,kind=excluded.kind,language=excluded.language,source=excluded.source,rights=excluded.rights,verified=false,updated_at=now(); ELSE SELECT to_jsonb(z) INTO old FROM public.admin_media z WHERE id=entity::uuid;UPDATE public.admin_media SET verified=true,updated_at=now() WHERE id=entity::uuid AND source<>'' AND rights<>''; IF NOT FOUND THEN RAISE EXCEPTION 'Source et autorisation requises.'; END IF; END IF;SELECT to_jsonb(z) INTO result FROM public.admin_media z WHERE id=entity::uuid;
ELSIF p_action LIKE 'lesson_%' THEN
 SELECT to_jsonb(z) INTO old FROM public.lesson_drafts z WHERE id=entity FOR UPDATE;
 IF p_action='lesson_save' THEN p:=p_data->'payload';IF coalesce(p->>'title','')='' OR jsonb_typeof(p->'body') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'body')=0 THEN RAISE EXCEPTION 'Titre et sections requis.'; END IF; INSERT INTO public.lesson_drafts(id,payload) VALUES(entity,p) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,status='draft',revision=lesson_drafts.revision+1,updated_at=now(); ELSE SELECT payload INTO p FROM public.lesson_drafts WHERE id=entity;IF coalesce(p->>'source_url','') !~ '^https://' THEN RAISE EXCEPTION 'Source du cours requise.'; END IF;UPDATE public.learning_lessons SET title=p->>'title',topic=p->>'topic',body=ARRAY(SELECT jsonb_array_elements_text(p->'body')),takeaway=ARRAY(SELECT jsonb_array_elements_text(p->'takeaway')),minutes=(p->>'minutes')::integer,source_url=p->>'source_url',published=true WHERE id=entity;IF NOT FOUND THEN RAISE EXCEPTION 'Cours existant requis pour préserver l’ordre du parcours.'; END IF;UPDATE public.lesson_drafts SET status='published',revision=revision+1,updated_at=now() WHERE id=entity; END IF;SELECT to_jsonb(z) INTO result FROM public.lesson_drafts z WHERE id=entity;
ELSIF p_action='report_update' THEN SELECT to_jsonb(z) INTO old FROM public.question_reports z WHERE id=entity::uuid;UPDATE public.question_reports SET status=p_data->>'status',reply=coalesce(p_data->>'reply','') WHERE id=entity::uuid; SELECT to_jsonb(z) INTO result FROM public.question_reports z WHERE id=entity::uuid;
END IF;
INSERT INTO public.admin_audit(actor,action,entity_id,before_data,after_data) VALUES(auth.uid(),p_action,entity,old,result); RETURN coalesce(result,'{}'); END $$;
REVOKE ALL ON FUNCTION public.admin_command(text,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.admin_command(text,jsonb) TO authenticated;
CREATE FUNCTION public.admin_users() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.admin_can('users') THEN RAISE EXCEPTION 'Accès refusé.' USING ERRCODE='42501'; END IF;RETURN (SELECT coalesce(jsonb_agg(to_jsonb(u)),'[]') FROM (SELECT p.id,p.display_name,p.parcours,p.locale,p.created_at,a.email,(SELECT coalesce(jsonb_agg(role),'[]') FROM public.user_roles WHERE user_id=p.id) roles FROM public.profiles p JOIN auth.users a ON a.id=p.id ORDER BY p.created_at DESC LIMIT 500) u);END $$;REVOKE ALL ON FUNCTION public.admin_users() FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.admin_users() TO authenticated;
CREATE FUNCTION public.admin_metrics(p_days integer DEFAULT 7) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Accès refusé.' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('questions',(SELECT count(*) FROM public.learning_questions),'tests',(SELECT count(*) FROM public.learning_tests),'attempts',(SELECT count(*) FROM public.learning_sessions WHERE started_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'new_users',(SELECT count(*) FROM public.profiles WHERE created_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'active_users',(SELECT count(DISTINCT user_id) FROM public.learning_sessions WHERE started_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'free_completed',(SELECT count(*) FROM public.learning_sessions WHERE kind='diagnostic' AND completed_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'exams',(SELECT count(*) FROM public.learning_sessions WHERE kind='exam' AND started_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'average_percent',(SELECT round(avg(correct::numeric/nullif(total,0)*100),1) FROM public.learning_sessions WHERE completed_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'exam_pass_percent',(SELECT round(avg(CASE WHEN correct::numeric/nullif(total,0)>=0.8 THEN 100 ELSE 0 END),1) FROM public.learning_sessions WHERE kind='exam' AND completed_at>=now()-make_interval(days=>least(greatest(p_days,1),30))),'pending',(SELECT count(*) FROM public.question_drafts WHERE status='pending'),'reports',(SELECT count(*) FROM public.question_reports WHERE status='open'),'revenue',null);END $$;REVOKE ALL ON FUNCTION public.admin_metrics(integer) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.admin_metrics(integer) TO authenticated;
CREATE FUNCTION public.start_configured_test(p_test uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.learning_tests; path text; qs jsonb; sid uuid; BEGIN SELECT parcours INTO path FROM public.profiles WHERE id=auth.uid();IF path IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour commencer.'; END IF; SELECT * INTO t FROM public.learning_tests WHERE id=p_test AND status='published';IF NOT FOUND OR NOT(path=ANY(t.pathways)) THEN RAISE EXCEPTION 'Test indisponible pour votre parcours.';END IF;
SELECT jsonb_agg(to_jsonb(q)-'ordering' ORDER BY q.ordering) INTO qs FROM (SELECT l.*,CASE WHEN t.selection='fixed' THEN array_position(t.question_ids,l.id)::float ELSE random() END ordering FROM public.learning_questions l WHERE published AND path=ANY(pathways) AND (cardinality(t.themes)=0 OR theme=ANY(t.themes) OR exam_theme=ANY(t.themes)) AND (t.selection<>'fixed' OR id=ANY(t.question_ids)) AND (t.kind<>'review' OR EXISTS(SELECT 1 FROM public.learning_sessions s CROSS JOIN LATERAL jsonb_array_elements(s.questions) WITH ORDINALITY v(q,n) WHERE s.user_id=auth.uid() AND s.completed_at IS NOT NULL AND v.q->>'id'=l.id AND (s.answers->>((v.n-1)::text))::integer IS DISTINCT FROM (v.q->>'answer')::integer)) ORDER BY ordering LIMIT t.question_count) q;
IF qs IS NULL OR jsonb_array_length(qs)<>t.question_count THEN RAISE EXCEPTION 'Questions publiées insuffisantes : aucun doublon ajouté.'; END IF;
INSERT INTO public.learning_sessions(user_id,parcours,kind,questions,total,deadline,test_id,test_rules) VALUES(auth.uid(),path,CASE WHEN t.kind='exam' OR NOT t.instant_feedback THEN 'exam' ELSE 'practice' END,qs,t.question_count,CASE WHEN t.duration_minutes>0 THEN now()+make_interval(mins=>t.duration_minutes) ELSE NULL END,t.id,to_jsonb(t)) RETURNING id INTO sid;RETURN sid;END $$;REVOKE ALL ON FUNCTION public.start_configured_test(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.start_configured_test(uuid) TO authenticated;